import hmac
import hashlib
import json
import os
import time
import secrets
from typing import Optional, Dict, Any

_SECRET_KEY = os.environ.get('API_SECRET_KEY', secrets.token_hex(32)).encode()
_ALGORITHM = 'sha256'
_MAC_LENGTH = 32  # Fixed: always use full 32-byte HMAC-SHA256

class SecureMessageBroker:
    """Message broker with HMAC-SHA256 authentication.

    Always uses full-length HMAC-SHA256 (32 bytes) for maximum security.
    """

    def __init__(self):
        self._nonce_cache: Dict[str, float] = {}
        self._max_age = 300  # 5 minute replay window

    def _cleanup_nonces(self):
        """Remove expired nonces to prevent memory exhaustion."""
        now = time.time()
        expired = [k for k, v in self._nonce_cache.items() if now - v > self._max_age * 2]
        for k in expired:
            del self._nonce_cache[k]

    def _compute_mac(self, message: bytes, context: bytes = b'') -> bytes:
        """Compute HMAC-SHA256 over message with optional context binding."""
        mac = hmac.new(_SECRET_KEY, context + message, hashlib.sha256)
        return mac.digest()

    def _parse_header(self, raw_message: bytes) -> Optional[Dict[str, Any]]:
        """Parse the message header. Format: JSON header + '|' + payload + '|' + mac_hex"""
        try:
            parts = raw_message.split(b'|', 2)
            if len(parts) != 3:
                return None
            header = json.loads(parts[0])
            if not isinstance(header, dict):
                return None
            return {
                'header': header,
                'payload': parts[1],
                'mac_hex': parts[2]
            }
        except (json.JSONDecodeError, UnicodeDecodeError):
            return None

    def _verify_mac(self, expected_mac: bytes, provided_mac_hex: bytes) -> bool:
        """Verify MAC with constant-time comparison.

        Always compares full 32-byte HMAC-SHA256 tags.
        Uses hmac.compare_digest for timing-safe comparison.
        """
        try:
            provided_mac = bytes.fromhex(provided_mac_hex.decode('ascii'))
        except (ValueError, UnicodeDecodeError):
            return False

        # Always compare full-length MACs
        if len(provided_mac) != _MAC_LENGTH:
            return False

        return hmac.compare_digest(expected_mac, provided_mac)

    def _check_replay(self, nonce: str, timestamp: float) -> bool:
        """Verify message freshness and prevent replay attacks."""
        now = time.time()
        if abs(now - timestamp) > self._max_age:
            return False
        if nonce in self._nonce_cache:
            return False
        self._nonce_cache[nonce] = now
        return True

    def authenticate_message(self, raw_message: bytes) -> Optional[Dict[str, Any]]:
        """Authenticate and parse an incoming message.

        Returns the verified payload or None if authentication fails.
        """
        self._cleanup_nonces()

        parsed = self._parse_header(raw_message)
        if parsed is None:
            return None

        header = parsed['header']
        payload = parsed['payload']
        mac_hex = parsed['mac_hex']

        # Validate required header fields
        required_fields = ['version', 'nonce', 'timestamp', 'sender']
        if not all(f in header for f in required_fields):
            return None

        version = header['version']
        if version != 1:
            return None  # Only support v1 with full-length MAC

        # Verify timestamp and nonce for replay protection
        try:
            timestamp = float(header['timestamp'])
        except (TypeError, ValueError):
            return None

        if not self._check_replay(header['nonce'], timestamp):
            return None

        # Compute expected MAC over header + payload
        header_bytes = json.dumps(header, sort_keys=True, separators=(',', ':')).encode()
        mac_input = header_bytes + b'|' + payload
        expected_mac = self._compute_mac(mac_input)

        # Verify the MAC (always full-length)
        if not self._verify_mac(expected_mac, mac_hex):
            return None

        # Parse the (now-authenticated) payload safely
        try:
            parsed_payload = json.loads(payload)
        except (json.JSONDecodeError, UnicodeDecodeError):
            return None

        return {
            'sender': header['sender'],
            'payload': parsed_payload,
            'verified': True,
            'protocol_version': version
        }

    def create_message(self, sender: str, payload: dict) -> bytes:
        """Create an authenticated message."""
        header = {
            'version': 1,
            'nonce': secrets.token_hex(16),
            'timestamp': time.time(),
            'sender': sender
        }

        payload_bytes = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
        header_bytes = json.dumps(header, sort_keys=True, separators=(',', ':')).encode()

        mac_input = header_bytes + b'|' + payload_bytes
        mac = self._compute_mac(mac_input)

        return header_bytes + b'|' + payload_bytes + b'|' + mac.hex().encode()


# Application layer using the broker
broker = SecureMessageBroker()

def handle_admin_command(raw_message: bytes) -> Dict[str, Any]:
    """Process an authenticated admin command."""
    result = broker.authenticate_message(raw_message)
    if result is None:
        return {'error': 'Authentication failed'}

    if result['sender'] != 'admin':
        return {'error': 'Insufficient privileges'}

    payload = result['payload']
    if not isinstance(payload, dict):
        return {'error': 'Invalid payload'}
    command = payload.get('command')

    if command == 'shutdown':
        return {'status': 'shutdown_initiated'}
    elif command == 'get_secrets':
        return {'status': 'ok', 'secrets': ['db_password', 'api_key']}
    elif command == 'delete_user':
        return {'status': 'ok', 'deleted': payload.get('target')}
    else:
        return {'error': 'Unknown command'}
